+/*
+ * File: complexity_exercises.rs
+ * Created Time: 2026-08-18
+ * Author: Hello Algo Team
+ */
+
+/* Iterative summation */
+fn sum_iter(n: i32) -> i32 {
+    let mut res = 0;
+    for i in 1..=n {
+        res += i;
+    }
+    res
+}
+
+/* Recursive summation */
+fn sum_recur(n: i32) -> i32 {
+    if n == 1 {
+        return 1;
+    }
+    n + sum_recur(n - 1)
+}
+
+/* Linear loop */
+fn linear_loop(n: i32) -> i32 {
+    let mut res = 0;
+    for i in 0..n {
+        res += i;
+    }
+    res
+}
+
+/* Quadratic loop */
+fn quadratic_loop(n: i32) -> i32 {
+    let mut res = 0;
+    for i in 0..n {
+        for j in i..n {
+            res += j;
+        }
+    }
+    res
+}
+
+/* Logarithmic loop */
+fn logarithmic_loop(mut n: i32) -> i32 {
+    while n > 1 {
+        n /= 2;
+    }
+    n
+}
+
+fn main() {
+    assert_eq!(sum_iter(1), 1);
+    assert_eq!(sum_recur(1), 1);
+    assert_eq!(sum_iter(4), 10);
